AURORA_FLUX.glsl_outline:
// Original 2D hash
float h21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float noise2(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    float a = h21(i);
    float b = h21(i + vec2(1.0, 0.0));
    float c = h21(i + vec2(0.0, 1.0));
    float d = h21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float fbm(vec2 p) {
    float v = 0.0, a = 0.5;
    for (int i = 0; i < 4; ++i) {
        v += a * noise2(p);
        p = p * 2.1 + 19.7;
        a *= 0.5;
    }
    return v;
}

void main() {
    vec2 uv = (fragCoord - 0.5 * iResolution) / iResolution.y;
    uv.x /= iAspect;

    float bassScale = 1.5 + iAudioBass * 1.2;
    float midWarp = 0.6 + iAudioMids * 1.0;
    float trebleShimmer = 0.08 * iAudioTreble;

    vec2 coord = uv * bassScale + vec2(sin(iTime * 0.15), cos(iTime * 0.11)) * 0.4;

    // Domain warp
    vec2 w = vec2(fbm(coord + iTime * 0.2), fbm(coord - iTime * 0.2 + 7.3));
    coord = coord + midWarp * (w - 0.5) * 2.0;

    // Sample warped field
    float f = fbm(coord + w * midWarp);
    f += trebleShimmer * noise2(coord * 8.0 + iTime * 0.5);

    // Color: navy to teal
    vec3 base = mix(vec3(0.02, 0.04, 0.10), vec3(0.05, 0.45, 0.55), f * f);
    base = mix(base, vec3(0.55, 0.15, 0.55), clamp(iAudioBass * 0.4, 0.0, 1.0) * f);
    base += vec3(0.9, 0.95, 1.0) * iBeatPulse * 0.45;
    base *= (0.6 + iAudioEnergy * 0.8) * iIntensity;

    // Vignette
    float vig = 1.0 - smoothstep(0.7, 1.4, length(uv));
    base *= vig;

    return half4(half3(clamp(base, 0.0, 1.0)), 1.0);
}

LIQUID_CHROME.glsl_outline:
float hash(vec2 p) { return fract(sin(p.x * 12.9898 + p.y * 78.233) * 43758.5453); }
float noise(vec2 p) {
    vec2 i = floor(p), f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i + vec2(0.,0.)), hash(i + vec2(1.,0.)), f.x),
               mix(hash(i + vec2(0.,1.)), hash(i + vec2(1.,1.)), f.x), f.y);
}
vec2 curl(vec2 p) { return vec2(-dFdy(p.y), dFdx(p.x)); }

void main() {
    vec2 uv = (fragCoord - 0.5 * iResolution) / iResolution.y;
    uv.x /= iAspect;

    float t = iTime * (1.5 + iAudioBass * 2.5 + iBeatPulse * 1.5);
    vec3 col = vec3(0.03, 0.03, 0.08);

    vec3 glowCol = mix(vec3(0.55, 0.10, 0.55), vec3(0.10, 0.55, 0.85), iAudioMids * 0.5);
    float horizonGlow = exp(-abs(uv.y - 0.15) * 8.0);
    col += glowCol * horizonGlow * (0.5 + iAudioEnergy * 0.5);

    if (uv.y < 0.15) {
        float depth = 0.4 / (0.15 - uv.y + 0.05);
        float hill = sin(uv.x * 5.0 + t * 0.3) * cos(uv.y * 3.0 + t * 0.2) * (0.08 + iAudioBass * 0.15);
        depth = 0.4 / (0.15 - uv.y + hill * 0.05);

        float gridX = abs(fract(uv.x * depth) - 0.5);
        float gridZ = abs(fract(t * 0.5) - 0.5);
        float line = smoothstep(0.42, 0.48, max(gridX, gridZ));

        vec3 gridColor = mix(vec3(0.10, 0.85, 0.95), vec3(0.85, 0.15, 0.85), fract(t * 0.05));
        col += gridColor * line * (0.6 + iAudioBass * 0.8)
               + vec3(0.9, 0.95, 1.0) * gridX * gridZ * iAudioTreble * 1.4;
    }

    if (uv.y >= 0.15) {
        float skyPulse = 0.04 * iAudioBass * sin(iTime * 0.5);
        col += glowCol * (0.05 + skyPulse);
    }

    col *= iIntensity;
    float vig = 1.0 - smoothstep(0.6, 1.4, length(uv));
    col *= vig;

    return half4(half3(clamp(col, 0.0, 1.0)), 1.0);
}

NEBULA_BLOOM.glsl_outline:
void main() {
    vec2 uv = (2.0 * fragCoord - iResolution) / min(iResolution.x, iResolution.y);
    float dist = length(uv);
    float angle = atan(uv.y, uv.x);

    float coreRadius = 0.35 + iAudioBass * 0.25;
    float coreGlow = 0.04 / abs(dist - coreRadius);

    float ringPhase = fract(dist * 2.5 - iTime * (0.6 + iAudioBass * 0.5));
    float ring = smoothstep(0.85, 0.98, ringPhase) * (1.0 - ringPhase);

    float rays = abs(sin(angle * 8.0 + iTime * 0.8 + sin(dist * 10.0))) * (0.3 + iAudioTreble * 0.7);

    vec3 primary = vec3(0.05, 0.45, 0.55);  // teal
    vec3 secondary = vec3(0.55, 0.15, 0.55); // magenta
    vec3 baseTint = primary;
    vec3 glowColor = primary * coreGlow;
    vec3 ringColor = secondary * ring * (1.5 + iAudioBass);
    vec3 rayColor = mix(primary, secondary, 0.5) * rays * (0.5 / (dist + 0.1));

    vec3 col = glowColor + ringColor + rayColor;
    col += baseTint * (0.02 / (dist * dist + 0.01));
    col = pow(col, vec3(0.9));
    col *= (1.0 - smoothstep(0.5, 1.5, length(uv)));

    return half4(half3(clamp(col, 0.0, 1.0)), 1.0);
}

PRISM_TUNNEL.glsl_outline:
void main() {
    vec2 uv = (fragCoord - 0.5 * iResolution) / iResolution.y;
    uv.x /= iAspect;

    float t = iTime;
    float camZ = t * (1.5 + iAudioBass * 2.5 + iBeatPulse * 1.5);
    vec3 col = vec3(0.02, 0.02, 0.05);

    vec3 primary = vec3(0.10, 0.85, 0.95);
    vec3 secondary = vec3(0.85, 0.15, 0.85);
    vec3 glowCol = mix(vec3(0.55, 0.10, 0.55), vec3(0.10, 0.55, 0.85), iAudioMids * 0.5);

    // Horizon glow
    float2 sunPos = vec2(0.0, 0.08);
    float sunDist = length(uv - sunPos);
    if (sunDist < 0.22) {
        float sunStripes = step(0.015, fract(uv.y * 35.0 - t * 0.2));
        vec3 sunCol = mix(secondary, primary, (uv.y - sunPos.y + 0.22) / 0.44);
        col = mix(col, sunCol, sunStripes * (1.0 + iAudioBass * 0.3));
    }

    if (uv.y < 0.05) {
        float depth = 0.4 / (0.06 - uv.y);
        float xCoord = uv.x * depth;
        float zCoord = depth + t * (4.0 + iAudioBass * 3.0);

        // Undulating hills
        float hill = sin(xCoord * 0.8) * cos(zCoord * 0.2) * (0.08 + iAudioBass * 0.15);
        depth = 0.4 / (0.06 - uv.y + hill * 0.05);
        xCoord = uv.x * depth;
        zCoord = depth + t * (4.0 + iAudioBass * 3.0);

        float gridX = abs(fract(xCoord) - 0.5);
        float gridZ = abs(fract(zCoord * 0.5) - 0.5);
        float line = smoothstep(0.42, 0.48, max(gridX, gridZ));

        vec3 gridColor = mix(primary, secondary, sin(zCoord * 0.1) * 0.5 + 0.5);
        float fog = clamp(1.0 / (depth * 0.12), 0.0, 1.0);
        col += gridColor * line * fog * (1.2 + iAudioMids * 0.8);
    }

    return half4(half3(clamp(col, 0.0, 1.0)), 1.0);
}

KINETIC_MANDALA.glsl_outline:
float hash12(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * 0.13);
    p3 += dot(p3, p3.yzx + 3.33);
    return fract((p3.x + p3.y) * p3.z);
}
mat2 rot2(float a) { float c = cos(a), s = sin(a); return mat2(c, -s, s, c); }
float sdEqTri(vec2 p, float r) {
    const float k = 1.73205081;
    p.x = abs(p.x) - r;
    p.y = p.y + r/k;
    if (p.x + k*p.y > 0.0) p = vec2(p.x - k*p.y, -k*p.x - p.y) / 2.0;
    p.x -= clamp(p.x, -2.0*r, 0.0);
    return -length(p) * sign(p.y);
}

void main() {
    vec2 uv = (fragCoord * 2.0 - iResolution) / min(iResolution.x, iResolution.y);
    float scale = 6.0 + iAudioMids * 5.0;
    vec2 gUv = uv * scale;
    vec2 cellId = floor(gUv);
    vec2 localUv = (fract(gUv) - 0.5);

    float cellHash = hash12(cellId);
    float fft = mix(iAudioBass, iAudioTreble, cellHash) * (0.5 + iAudioMids);
    float cellBeat = mix(iBeatPulse, iAudioTreble, cellHash * 0.5 + iAudioBass * 0.5);

    float beat = smoothstep(0.4, 0.8, fft * (1.0 + iAudioBass));
    float size = (fft * 0.4 + 0.15) * (1.0 + beat * 0.6);
    float angle = iTime * (0.2 + fft * 2.0) + cellHash * 6.28;

    vec2 triUv = rot2(angle) * localUv;
    float d = sdEqTri(triUv, size);

    vec3 primary = vec3(0.10, 0.85, 0.95);
    vec3 secondary = vec3(0.85, 0.15, 0.85);
    vec3 col = mix(primary, secondary, fft);
    float edge = smoothstep(0.015, 0.0, abs(d) - 0.003);
    float glow = exp(-max(d, 0.0) * 20.0);
    vec3 finalCol = col * edge * (1.0 + fft * 3.0) + col * glow * (0.5 + fft * 2.0 + iBeatPulse);
    finalCol *= 1.0 - smoothstep(0.5, 1.2, length(uv * 0.8));

    return half4(half3(clamp(finalCol, 0.0, 1.0)), 1.0);
}

PULSE_GEOMETRY.glsl_outline:
float hash12(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * 0.13);
    p3 += dot(p3, p3.yzx + 3.33);
    return fract((p3.x + p3.y) * p3.z);
}

void main() {
    vec2 uv = (fragCoord * 2.0 - iResolution) / min(iResolution.x, iResolution.y);
    float cellHash = hash12(uv * 4.0);

    float fftBass = mix(0.0, iAudioBass, cellHash);
    float fftMids = mix(0.0, iAudioMids, cellHash);
    float fftTreble = mix(0.0, iAudioTreble, cellHash);
    float fftEnergy = mix(0.0, iAudioEnergy, cellHash);
    float beat = smoothstep(0.3, 0.7, iBeatPulse);

    float baseSize = 0.3 + fftEnergy * 0.4;
    float zoom = 1.5 + fftBass * 2.0 + iBeatPulse * 1.5;
    float angle = iTime * (0.5 + fftMids * 1.5) + cellHash * 3.14;

    vec2 centered = uv / zoom;
    vec2 rotated = vec2(cos(angle) * centered.x - sin(angle) * centered.y,
                        sin(angle) * centered.x + cos(angle) * centered.y);

    float d = length(rotated) - baseSize;

    vec3 primary = vec3(0.10, 0.85, 0.95);
    vec3 secondary = vec3(0.85, 0.15, 0.85);
    vec3 col = mix(primary, secondary, iBeatPulse);

    float edge = smoothstep(0.02, 0.0, abs(d));
    float glow = exp(-abs(d) * 15.0);

    vec3 finalCol = col * edge * (1.0 + iBeatPulse * 2.0) + col * glow * (0.5 + iBeatPulse);
    finalCol *= 1.0 - smoothstep(0.5, 1.0, length(uv));

    return half4(half3(clamp(finalCol, 0.0, 1.0)), 1.0);
}
